def slug(t):return re.sub('[^a-z0-9]+','-',t.lower()).strip('-') or 'section'
def notes():
 out=[]
 for p in sorted((ROOT/'content/notes').glob('*.md')):
  if not re.fullmatch('[a-z0-9-]+',p.stem):raise ValueError(p)
