  date.fromisoformat(m['date']); m.update(slug=p.stem,body=x[2].strip(),kind=m.get('kind','blog'),reviewed=m.get('reviewed')=='true'); m['minutes']=max(1,math.ceil(len(m['body'].split())/220));out.append(m)
