N=notes(); INDEX=[dict(title=n['title'],description=n['description'],kind='Essay' if n['kind']=='essay' else 'Blog',url='notes/'+n['slug']+'.html') for n in N]+[dict(title=p['title'],description=p['description'],kind='Research',url='research/'+p['slug']+'.html') for p in S['research']]+[dict(title=p['name'],description=p['description'],kind='Project',url='projects.html#'+slug(p['name'])) for p in S['projects']]
