OUT.mkdir();(OUT/'.nojekyll').touch();shutil.copytree(ROOT/'assets',OUT/'assets')
if (ROOT/'content/media').exists():shutil.copytree(ROOT/'content/media',OUT/'media')
hero=f'<header class="hero"><div class="clockline"><span>{e(S["location"])}</span><span data-clock>PKT</span></div><h1>Abdul Wasea</h1><p class="role">Software engineer and independent researcher.</p><p>I build AI agents, developer tools and full-stack software. My interests are in long-horizon coding agents, memory systems and software reliability.</p><p>Founder of {link("https://zhilo.vercel.app/","Zhilo Labs")}.</p><div class="social">{link(S["github"],"GitHub ↗")}{link(S["linkedin"],"LinkedIn ↗")}{link(S["x"],"X ↗")}{link("mailto:"+S["email"],"Email ↗")}</div></header>'
