page('projects.html','Projects','Selected software projects and open-source contributions.',head('Projects','Software, infrastructure and tools I’m building.')+section('Selected work',projects())+section('Open-source contributions',contributions()),'Projects')
page('research.html','Research','Research on AI agent memory, verification and the economics of automation.',head('Research','Independent work on agent memory, verification and AI systems.')+section('Papers',papers(),link('https://github.com/abdulwasea89/research_papers','Manuscripts ↗'))+section('Research directions',entry('Long-horizon agent reliability','Memory validity, dependency tracking and verification budgets.')+entry('Evaluation and software correctness','Testing agent behavior under changing repository state and partial observability.')+entry('AI and work','Task automation, human judgment and the distribution of productivity gains.')),'Research')
