(OUT/'writing.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><link rel="canonical" href="{e(BASE)}/blogs.html"><meta http-equiv="refresh" content="0; url=blogs.html"><title>Blogs</title></head><body><a href="blogs.html">Go to Blogs</a></body></html>')
for n in N:
 html,toc=article_body(n['body']); isessay=n['kind']=='essay'; group='Essays' if isessay else 'Blogs'; back='essays.html' if isessay else 'blogs.html'; nav=''.join(link('#'+id,t) for id,t in toc); related=[p for p in N if p!=n and p['kind']==n['kind']][:2]; relatedhtml=''.join(link(p['slug']+'.html',p['title']) for p in related); draft='' if n['reviewed'] else '<p class="draft">Editorial draft for review. Not yet presented as the site owner’s authored work.</p>'
 body=f'<div class="article-layout"><article class="article">{link("../"+back,"← "+group,"small-link")}<h1>{e(n["title"])}</h1><p class="deck">{e(n["description"])}</p><div class="article-meta"><time datetime="{e(n["date"])}">{e(n["date"])}</time><span>{e(n["tag"])}</span><span>{n["minutes"]} min read</span></div>{draft}<div class="article-tools"><button data-copy>Copy article</button>{link("../"+back,"All posts")}</div><div class="body">{html}</div><div class="related"><h2>Related {"essays" if isessay else "articles"}</h2>{relatedhtml}</div></article><aside class="toc" aria-label="Table of contents"><strong>On this page</strong>{nav}</aside></div>'
 schema={'@type':'BlogPosting','headline':n['title'],'description':n['description'],'datePublished':n['date'],'author':{'@id':BASE+'/#person'},'mainEntityOfPage':BASE+'/notes/'+n['slug']+'.html','inLanguage':'en'};page('notes/'+n['slug']+'.html',n['title'],n['description'],body,group,schema,not n['reviewed'],True)
for p in S['research']:
 abstract=''.join('<p>'+e(x)+'</p>' for x in p['abstract'].split('\n\n')); highlights=''.join('<li>'+e(x)+'</li>' for x in p['highlights']); body=f'<div class="article-layout"><article class="article">{link("../research.html","← Research","small-link")}<h1>{e(p["title"])}</h1><p class="deck">{e(p["description"])}</p><div class="article-meta"><span>Abdul Wasea</span><span>{e(p["year"])}</span><span>{e(p["tag"])}</span></div><div class="article-tools">{link(p["paper_url"],"Read manuscript on SSRN ↗")}{link(p["repo_url"],"Research repository ↗")}</div><div class="body"><h2 id="overview">Overview</h2><p class="draft">Portfolio summary, not a verbatim abstract. Consult the manuscript for the full argument.</p>{abstract}<h2 id="ideas">Key ideas</h2><ul>{highlights}</ul><h2 id="manuscript">Manuscript</h2><p>{link(p["paper_url"],"Open the SSRN record ↗")}</p></div></article><aside class="toc"><strong>On this page</strong>{link("#overview","Overview")}{link("#ideas","Key ideas")}{link("#manuscript","Manuscript")}</aside></div>';schema={'@type':'ScholarlyArticle','headline':p['title'],'description':p['description'],'author':{'@id':BASE+'/#person'},'datePublished':p['year'],'sameAs':p['paper_url']};page('research/'+p['slug']+'.html',p['title'],p['description'],body,'Research',schema,False,True)
